    {
      "action": "Separate quotation verification from speaker verification",
      "mechanism": "Explicit review states prevent verified wording from implying verified identity; unknown remains a valid speaker value.",
      "implementation": "Show attribution status beside search results and saved quotes. Require reviewer confirmation for verified identity; export unresolved identities as “Speaker unknown—attribution unverified.”",
      "check": "Verify wording while leaving the speaker unresolved; confirm search, collections, and exports never present the imported name as verified.",
      "risk": "A single combined verification badge would recreate ambiguity."
    },
    {
      "action": "Propagate corrections through append-only quote revisions",
      "mechanism": "Stable quote references resolve current corrections while immutable revisions preserve what researchers previously saved or exported.",
      "implementation": "Retain imported text and labels. Append corrections with reviewer identity, reason, and prior revision. Collections retain saved revisions while displaying current values and change notices.",
      "check": "Correct a speaker after saving the quote in two collections; both update visibly, while prior revisions and reviewer identities remain retrievable.",
      "risk": "Silent updates could conceal consequential attribution changes."
    },
    {
      "action": "Anchor quotes across segments to reviewed audio",
      "mechanism": "Ordered source spans and separately reviewed audio bounds avoid treating unreliable segment timestamps as authoritative quote boundaries.",
      "implementation": "Store each quote’s segment IDs, text offsets, recording ID, and revisioned audio intervals. Provide contextual playback and adjustable bounds; export a resolving audio link with interval-review status.",
      "check": "Save a boundary-crossing quote with an unresolved speaker; adjust incorrect bounds and verify its export replays the complete passage without asserting identity.",
      "risk": "Unavailable recordings or restrictive permissions can break playback."
    }
  ],
  "abstention_reason": ""
}
